import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken", "Rice", "Vegetables", "Bread", "Almonds", "Salmon"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Chicken": 2,
        "Rice": 3,
        "Vegetables": 3,
        "Bread": 2,
        "Almonds": 4,
        "Salmon": 10,
    },
    "content": {
        # nutrient -> food -> amount per unit
        "protein": {
            "Chicken": 16,
            "Rice": 11,
            "Vegetables": 1,
            "Bread": 6,
            "Almonds": 2,
            "Salmon": 19,
        },
        "carbs": {
            "Chicken": 8,
            "Rice": 24,
            "Vegetables": 5,
            "Bread": 26,
            "Almonds": 11,
            "Salmon": 20,
        },
        "calories": {
            "Chicken": 50,
            "Rice": 90,
            "Vegetables": 164,
            "Bread": 165,
            "Almonds": 51,
            "Salmon": 238,
        },
    },
    "requirement": {
        "protein": 58,
        "carbs": 150,
        "calories": 2392,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.servings = pyo.Var(
        model.I, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.servings[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(
            d["content"][n][i] * m.servings[i] for i in m.I
        ) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


